const API_KEY = "YOUR_API_KEY";
const BASE_URL = "https://open-api.saleshandy.com/v1";

// Step 1: Fetch all sequences
let sequences = [];
try {
  const seqResponse = await this.helpers.httpRequest({
    method: "GET",
    url: `${BASE_URL}/sequences`,
    headers: {
      "x-api-key": API_KEY,
    },
    json: true,
  });
  sequences = seqResponse.data || seqResponse.sequences || seqResponse || [];
} catch (err) {
  sequences = [];
  console.log("Sequences fetch error:", err.message);
}

// Step 2: Paginate through all email accounts
const allEmails = [];
let page = 1;
let hasMore = true;

while (hasMore) {
  try {
    const response = await this.helpers.httpRequest({
      method: "GET",
      url: `${BASE_URL}/email-accounts`,
      qs: {
        page,
        limit: 100,
      },
      headers: {
        "x-api-key": API_KEY,
      },
      json: true,
    });

    const accounts = response.data || response.emailAccounts || [];

    if (!Array.isArray(accounts) || accounts.length === 0) {
      hasMore = false;
      break;
    }

    allEmails.push(...accounts);
    hasMore = accounts.length === 100;
    page++;
  } catch (err) {
    console.log(`Email accounts fetch error on page ${page}:`, err.message);
    hasMore = false;
  }
}

// Step 3: Build domain map with health scores
const domainMap = {};

for (const account of allEmails) {
  const email = account.email || account.fromEmail || "";
  const domain = email.split("@")[1];

  if (!domain) continue;

  if (!domainMap[domain]) {
    domainMap[domain] = {
      accounts: [],
      totalAccounts: 0,
      avgHealthScore: 0,
      healthScores: [],
    };
  }

  const healthScore = account.healthScore
    || account.health_score
    || account.emailHealth
    || 0;

  domainMap[domain].accounts.push({
    email: email,
    healthScore: healthScore,
    fromName: account.fromName || account.from_name || "",
    status: account.status || "unknown",
    dailyLimit: account.dailyLimit || account.daily_limit || null,
    sentToday: account.sentToday || account.sent_today || null,
  });

  domainMap[domain].totalAccounts++;
  domainMap[domain].healthScores.push(healthScore);
}

// Calculate averages per domain
for (const domain of Object.keys(domainMap)) {
  const scores = domainMap[domain].healthScores;
  domainMap[domain].avgHealthScore = scores.length > 0
    ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length)
    : 0;
  delete domainMap[domain].healthScores;
}

// Step 4: Build summary
const allHealthScores = allEmails
  .map(e => e.healthScore || e.health_score || 0)
  .filter(s => s > 0);

const avgOverallHealth = allHealthScores.length > 0
  ? Math.round(allHealthScores.reduce((a, b) => a + b, 0) / allHealthScores.length)
  : 0;

const domainSummary = Object.entries(domainMap)
  .map(([domain, data]) => ({
    domain,
    totalAccounts: data.totalAccounts,
    avgHealthScore: data.avgHealthScore,
    status: data.avgHealthScore >= 90 ? "excellent"
      : data.avgHealthScore >= 80 ? "good"
      : data.avgHealthScore >= 70 ? "warning"
      : "critical",
  }))
  .sort((a, b) => b.avgHealthScore - a.avgHealthScore);

return [
  {
    json: {
      reportDate: new Date().toISOString(),
      totalEmailAccounts: allEmails.length,
      totalDomains: Object.keys(domainMap).length,
      avgOverallHealthScore: avgOverallHealth,
      totalSequences: Array.isArray(sequences) ? sequences.length : 0,
      sequences: sequences,
      domainSummary: domainSummary,
      domainMap: domainMap,
    },
  },
];

const input = $input.first().json;
const domainMap = input.domainMap || {};
const sequences = input.sequences || [];

// Build per-sequence stats
const sequenceStats = [];
for (const seq of sequences) {
  sequenceStats.push({
    id: seq.id || seq.sequenceId || null,
    name: seq.name || seq.sequenceName || "Unknown",
    status: seq.status || "unknown",
    totalProspects: seq.totalProspects || seq.total_prospects || 0,
    sent: seq.sent || seq.totalSent || 0,
    opened: seq.opened || seq.totalOpened || 0,
    replied: seq.replied || seq.totalReplied || 0,
    bounced: seq.bounced || seq.totalBounced || 0,
    openRate: seq.sent > 0
      ? ((seq.opened || seq.totalOpened || 0) / (seq.sent || seq.totalSent || 1) * 100).toFixed(1) + "%"
      : "0.0%",
    replyRate: seq.sent > 0
      ? ((seq.replied || seq.totalReplied || 0) / (seq.sent || seq.totalSent || 1) * 100).toFixed(1) + "%"
      : "0.0%",
    bounceRate: seq.sent > 0
      ? ((seq.bounced || seq.totalBounced || 0) / (seq.sent || seq.totalSent || 1) * 100).toFixed(1) + "%"
      : "0.0%",
  });
}

// Flag domains needing attention
const flaggedDomains = input.domainSummary
  .filter(d => d.status === "warning" || d.status === "critical")
  .map(d => ({
    domain: d.domain,
    avgHealthScore: d.avgHealthScore,
    status: d.status,
    accountCount: d.totalAccounts,
    action: d.status === "critical"
      ? "PAUSE sending immediately — health score below 70"
      : "MONITOR closely — health score between 70-79",
  }));

// Top performing domains
const topDomains = input.domainSummary
  .filter(d => d.status === "excellent" || d.status === "good")
  .slice(0, 5)
  .map(d => ({
    domain: d.domain,
    avgHealthScore: d.avgHealthScore,
    status: d.status,
    accountCount: d.totalAccounts,
    action: d.avgHealthScore >= 90
      ? "Safe to increase volume 10-15%"
      : "Maintain current volume",
  }));

return [
  {
    json: {
      report: {
        title: "Domain Health & Campaign Report",
        generatedAt: new Date().toISOString(),
        summary: {
          totalEmailAccounts: input.totalEmailAccounts,
          totalDomains: input.totalDomains,
          avgOverallHealthScore: input.avgOverallHealthScore,
          totalSequences: input.totalSequences,
          domainsNeedingAttention: flaggedDomains.length,
          healthyDomains: input.domainSummary.filter(d => d.status === "excellent" || d.status === "good").length,
        },
        domainHealth: input.domainSummary,
        flaggedDomains: flaggedDomains,
        topPerformers: topDomains,
        campaignStats: sequenceStats,
        domainDetail: domainMap,
      },
    },
  },
];

